namespace worldgen {namespace {
AtmosphereComposition normalized_atmosphere(AtmosphereComposition a){double s=0;for(const auto&[f,x]:a.mole_fraction){(void)f;s+=std::max(0.0,x);}if(!(s>0))throw std::invalid_argument("atmosphere has zero composition");for(auto&[f,x]:a.mole_fraction){(void)f;x=std::max(0.0,x)/s;}return a;}
double activity_factor(const PlanetProfile&p,const TidalHeatingResult&t){if(p.geology_regime=="active")return 1.0;if(p.geology_regime=="inactive")return 0.22;if(p.geology_regime=="cryogenic")return 0.18;if(p.geology_regime=="mixed")return 0.82;const double size=std::pow(std::max(p.world_mass_earth,0.02),0.28);const double tide=std::clamp(t.host_surface_flux_w_m2/0.12,0.0,2.0);return std::clamp(0.22+0.55*size+0.35*tide,0.15,1.45);}
RasterF build_temperature(const PlanetProfile&p,const SphereGrid&g,const RasterF&elev,const GreenhouseResult&green){RasterF t(g.height(),g.width());const double pbar=p.atmosphere.surface_pressure_pa/1e5;const double meridional=12.0+38.0/(1.0+std::pow(std::max(pbar,0.01),0.55));double mean_shape=0;for(std::size_t y=0;y<g.height();++y){const double s=std::sin(g.lat(y)*kDegToRad);mean_shape+=s*s*g.area_weight(y)*static_cast<double>(g.width());}const double lapse=std::clamp(6.5*p.gravity_m_s2()/9.80665,0.4,12.0);for(std::size_t y=0;y<g.height();++y){const double s=std::sin(g.lat(y)*kDegToRad);const double lat_anom=-meridional*(s*s-mean_shape);for(std::size_t x=0;x<g.width();++x)t(y,x)=static_cast<float>(std::max(20.0,green.surface_temperature_k+lat_anom-lapse*std::max(0.0,static_cast<double>(elev(y,x)))));}return t;}
std::vector<VolatileInventory> inventories(const PlanetProfile&p){std::vector<VolatileInventory>v;v.reserve(p.volatiles.size());for(const auto&[f,x]:p.volatiles){(void)f;v.push_back(x);}return v;}
RasterF liquid_mask_from_depth(const RasterF&d){RasterF m(d.height(),d.width());for(std::size_t i=0;i<d.size();++i)m.span()[i]=d.span()[i]>0?1.0f:0.0f;return m;}
double surface_area_m2(const SphereGrid&g){const double r=g.radius_km()*1000.0;return 4.0*kPi*r*r;}
void add_volatile_flux_fields(const ChemicalDatabase&db,const PlanetProfile&p,const SphereGrid&g,const RasterF&t,const VolatileCycleResult&v,FieldSet&fields){const double area=surface_area_m2(g),gravity=p.gravity_m_s2();const auto&depth=v.surface_liquid.depth_m;for(const auto&part:v.species){const auto*s=db.find(part.formula);if(!s)continue;const double pp=part.atmosphere_mass_kg*gravity/area;RasterF precip(g.height(),g.width(),0.0f),evap(g.height(),g.width(),0.0f);const double rho=std::max(part.liquid_density_kg_m3,1.0);const double turnover=(part.formula=="H2O")?16.0:((part.formula=="CH4"||part.formula=="C2H6")?2.2:5.0);for(std::size_t y=0;y<g.height();++y){const double lat=std::cos(g.lat(y)*kDegToRad);for(std::size_t x=0;x<g.width();++x){const double ps=saturation_vapor_pressure_pa(*s,t(y,x));const double super=std::max(0.0,pp/std::max(ps,1e-20)-1.0);const double cond=super/(1.0+super);const double column=pp/gravity;const double kgm2y=column*turnover*cond*(0.35+0.65*lat*lat);precip(y,x)=static_cast<float>(1000.0*kgm2y/rho);if(depth(y,x)>0&&ps>pp){const double deficit=(ps-pp)/gravity;evap(y,x)=static_cast<float>(1000.0*turnover*0.18*deficit/rho);}}}fields["precip_"+part.formula+"_mm_year"]=std::move(precip);fields["evap_"+part.formula+"_mm_year"]=std::move(evap);}}
RasterF total_precip(const FieldSet&fields,std::size_t h,std::size_t w){RasterF out(h,w,0.0f);for(const auto&[name,r]:fields)if(name.rfind("precip_",0)==0){for(std::size_t i=0;i<out.size();++i)out.span()[i]+=r.span()[i];}return out;}
double weighted_volume_km3(const SphereGrid&g,const RasterF&meters){const double area=surface_area_m2(g);double m3=0;for(std::size_t y=0;y<g.height();++y)for(std::size_t x=0;x<g.width();++x)m3+=static_cast<double>(meters(y,x))*area*g.area_weight(y);return m3/1e9;}
void geomorphic_step(const SphereGrid&g,const VolatileCycleResult&vol,FieldSet&fields,GenerationDiagnostics&diag){auto it=fields.find("elevation_km");if(it==fields.end())return;auto&elev=it->second;SphericalRasterOps ops(g);auto grad=ops.metric_gradient(elev);RasterD slope(g.height(),g.width());for(std::size_t i=0;i<slope.size();++i)slope.span()[i]=std::hypot(grad.first.span()[i],grad.second.span()[i]);auto sn=normalize01(slope,true);auto rain=total_precip(fields,g.height(),g.width());auto rn=normalize01(rain,true);RasterF erosion(g.height(),g.width());for(std::size_t i=0;i<erosion.size();++i){const double e=6.0*vol.geomorphic_stream_power_factor*std::pow(std::max(0.0,static_cast<double>(rn.span()[i])),0.72)*std::pow(std::max(0.0,static_cast<double>(sn.span()[i])),0.82);erosion.span()[i]=static_cast<float>(std::clamp(e,0.0,18.0));}auto dep=ops.gaussian_filter(erosion,1.1,1.55);double er=0,de=0;for(std::size_t y=0;y<g.height();++y)for(std::size_t x=0;x<g.width();++x){const double aw=g.area_weight(y);er+=erosion(y,x)*aw;de+=dep(y,x)*aw;}const double retention=0.88;const double scale=de>0?retention*er/de:0;for(float&x:dep.span())x=static_cast<float>(x*scale);for(std::size_t i=0;i<elev.size();++i)elev.span()[i]+=static_cast<float>((static_cast<double>(dep.span()[i])-static_cast<double>(erosion.span()[i]))/1000.0);diag.eroded_volume_km3+=weighted_volume_km3(g,erosion);diag.deposited_volume_km3+=weighted_volume_km3(g,dep);diag.exported_sediment_volume_km3+=weighted_volume_km3(g,erosion)*(1.0-retention);fields["erosion_m_last"]=std::move(erosion);fields["deposition_m_last"]=std::move(dep);}
std::string esc(const std::string&s){std::string o;for(char c:s){if(c=='"'||c=='\\')o+='\\';o+=c;}return o;}
}
GeneratedWorld generate_planet(const PlanetProfile&profile,ProgressTracker*progress){profile.validate();GeneratedWorld out;out.atmosphere=normalized_atmosphere(profile.atmosphere);ChemicalDatabase db;RngPool pool(profile.seed);SphereGrid grid(profile.width,profile.height,profile.radius_km());if(progress)progress->begin("generate",8,"exoworld generation");out.greenhouse=estimate_greenhouse(out.atmosphere,profile.star_luminosity_solar,profile.orbital_distance_au,profile.bond_albedo);out.tides=tidal_heating(profile.orbit,profile.world_mass_earth,profile.radius_km());if(progress)progress->advance("generate",1,"radiation + tides");auto rt=pool("terrain");auto broad=hybrid_multifractal(grid,rt,profile.noise,kTerrainBlend,std::max(3,profile.noise.octaves-2),std::max(static_cast<double>(grid.height())/8.0,4.0));auto fine=hybrid_multifractal(grid,rt,profile.noise,kTerrainBlend,profile.noise.octaves,std::max(static_cast<double>(grid.height())/26.0,2.2));auto structure=hybrid_noise01(grid,rt,profile.noise,kTectonicBlend,std::max(4,profile.noise.octaves-1),std::max(static_cast<double>(grid.height())/12.0,3.0));const double active=activity_factor(profile,out.tides);RasterF elev(grid.height(),grid.width());for(std::size_t i=0;i<elev.size();++i){const double ridge=std::max(0.0,1.0-2.0*std::abs(static_cast<double>(structure.span()[i])-.5));const double relief=profile.relief_scale*((0.72+0.58*active)*broad.span()[i]+(0.16+0.30*active)*fine.span()[i]+1.65*active*ridge*ridge-0.42*active);elev.span()[i]=static_cast<float>(relief);}out.fields["elevation_km"]=std::move(elev);if(progress)progress->advance("generate",1,"base geodynamics + terrain");out.fields["temperature_k"]=build_temperature(profile,grid,out.fields.at("elevation_km"),out.greenhouse);out.volatile_cycle=solve_volatile_cycle(db,grid,out.fields.at("elevation_km"),out.fields.at("temperature_k"),out.atmosphere.surface_pressure_pa,profile.gravity_m_s2(),inventories(profile),profile.ice_trapping_efficiency);out.diagnostics.initial_liquid_volume_km3=out.volatile_cycle.surface_liquid.volume_m3/1e9;if(progress)progress->advance("generate",1,"volatile phase partition + initial hypsometric fill");out.geodynamics=classify_geodynamics(profile.world_mass_earth,profile.world_radius_earth,profile.world_age_gyr,out.greenhouse.surface_temperature_k,out.tides.host_surface_flux_w_m2,out.volatile_cycle);if(out.geodynamics.cryovolcanism_index>0.02){auto rc=pool("cryogeology");auto cryo=hybrid_noise01(grid,rc,profile.noise,{.30,.42,.08,.20},std::max(4,profile.noise.octaves-1),std::max(static_cast<double>(grid.height())/18.0,2.5));auto&e=out.fields.at("elevation_km");for(std::size_t i=0;i<e.size();++i){const double dome=std::pow(std::max(0.0,static_cast<double>(cryo.span()[i])-.62)/.38,2.0);e.span()[i]+=static_cast<float>(0.9*out.geodynamics.cryovolcanism_index*dome);}}out.fields["temperature_k"]=build_temperature(profile,grid,out.fields.at("elevation_km"),out.greenhouse);out.volatile_cycle=solve_volatile_cycle(db,grid,out.fields.at("elevation_km"),out.fields.at("temperature_k"),out.atmosphere.surface_pressure_pa,profile.gravity_m_s2(),inventories(profile),profile.ice_trapping_efficiency);out.fields["surface_liquid_depth_m"]=out.volatile_cycle.surface_liquid.depth_m;out.fields["surface_liquid_mask"]=liquid_mask_from_depth(out.volatile_cycle.surface_liquid.depth_m);if(progress)progress->advance("generate",1,"cryogeology + dynamic surface liquid");add_volatile_flux_fields(db,profile,grid,out.fields.at("temperature_k"),out.volatile_cycle,out.fields);if(progress)progress->advance("generate",1,"multicomponent precipitation/evaporation");for(int it=0;it<profile.erosion_iterations;++it){geomorphic_step(grid,out.volatile_cycle,out.fields,out.diagnostics);out.fields["temperature_k"]=build_temperature(profile,grid,out.fields.at("elevation_km"),out.greenhouse);out.volatile_cycle=solve_volatile_cycle(db,grid,out.fields.at("elevation_km"),out.fields.at("temperature_k"),out.atmosphere.surface_pressure_pa,profile.gravity_m_s2(),inventories(profile),profile.ice_trapping_efficiency);out.fields["surface_liquid_depth_m"]=out.volatile_cycle.surface_liquid.depth_m;out.fields["surface_liquid_mask"]=liquid_mask_from_depth(out.volatile_cycle.surface_liquid.depth_m);add_volatile_flux_fields(db,profile,grid,out.fields.at("temperature_k"),out.volatile_cycle,out.fields);}if(progress)progress->advance("generate",1,"volatile-specific erosion/deposition");out.photochemistry=photochemistry_products(out.atmosphere,profile.star_uv_relative_earth);RasterF heat(grid.height(),grid.width(),static_cast<float>(out.geodynamics.internal_heat_flux_w_m2)),cryo(grid.height(),grid.width(),static_cast<float>(out.geodynamics.cryovolcanism_index));out.fields["internal_heat_flux_w_m2"]=std::move(heat);out.fields["cryovolcanism_index"]=std::move(cryo);out.diagnostics.final_liquid_volume_km3=out.volatile_cycle.surface_liquid.volume_m3/1e9;out.metadata["geodynamic_regime"]=std::string(geodynamic_regime_name(out.geodynamics.regime));out.metadata["dominant_surface_liquid"]=out.volatile_cycle.dominant_surface_liquid;out.metadata["model"]="reduced-order coupled exoworld core; global volatile inventory + spherical hypsometry + condensable-specific geomorphology";if(progress){progress->advance("generate",1,"photochemistry + diagnostics");progress->finish("generate","complete");}return out;}
void reconcile_global_planet_fields(const PlanetProfile&p,FieldSet&fields,VolatileCycleResult*cycle,ProgressTracker*progress){const auto ei=fields.find("elevation_km"),ti=fields.find("temperature_k");if(ei==fields.end()||ti==fields.end())throw std::invalid_argument("global reconciliation needs elevation_km and temperature_k");SphereGrid grid(ei->second.width(),ei->second.height(),p.radius_km());ChemicalDatabase db;if(progress)progress->begin("reconcile",2,"global volatile/conservation reconciliation");auto v=solve_volatile_cycle(db,grid,ei->second,ti->second,p.atmosphere.surface_pressure_pa,p.gravity_m_s2(),inventories(p),p.ice_trapping_efficiency);fields["surface_liquid_depth_m"]=v.surface_liquid.depth_m;fields["surface_liquid_mask"]=liquid_mask_from_depth(v.surface_liquid.depth_m);if(progress)progress->advance("reconcile",1,"hypsometric liquid level");for(auto it=fields.begin();it!=fields.end();){if(it->first.rfind("precip_",0)==0||it->first.rfind("evap_",0)==0)it=fields.erase(it);else ++it;}add_volatile_flux_fields(db,p,grid,ti->second,v,fields);if(cycle)*cycle=std::move(v);if(progress){progress->advance("reconcile",1,"condensable fluxes");progress->finish("reconcile");}}
void write_generation_summary_json(const std::filesystem::path&path,const PlanetProfile&p,const GeneratedWorld&w){std::filesystem::create_directories(path.parent_path().empty()?std::filesystem::path("."):path.parent_path());std::ofstream o(path);if(!o)throw std::runtime_error("cannot write generation summary");o<<std::setprecision(12)<<"{\n  \"seed\": "<<p.seed<<",\n  \"resolution\": ["<<p.width<<", "<<p.height<<"],\n  \"surface_pressure_pa\": "<<w.atmosphere.surface_pressure_pa<<",\n  \"equilibrium_temperature_k\": "<<w.greenhouse.equilibrium_temperature_k<<",\n  \"surface_temperature_k_reduced_order\": "<<w.greenhouse.surface_temperature_k<<",\n  \"greenhouse_delta_k\": "<<w.greenhouse.greenhouse_delta_k<<",\n  \"tidal_heat_flux_w_m2\": "<<w.tides.host_surface_flux_w_m2<<",\n  \"geodynamic_regime\": \""<<esc(std::string(geodynamic_regime_name(w.geodynamics.regime)))<<"\",\n  \"dominant_surface_liquid\": \""<<esc(w.volatile_cycle.dominant_surface_liquid)<<"\",\n  \"surface_liquid_level_km\": "<<w.volatile_cycle.surface_liquid.level_km<<",\n  \"surface_liquid_volume_km3\": "<<w.volatile_cycle.surface_liquid.volume_m3/1e9<<",\n  \"eroded_volume_km3\": "<<w.diagnostics.eroded_volume_km3<<",\n  \"deposited_volume_km3\": "<<w.diagnostics.deposited_volume_km3<<",\n  \"photochemistry\": [";for(std::size_t i=0;i<w.photochemistry.size();++i){if(i)o<<',';o<<"{\"product\":\""<<esc(w.photochemistry[i].product)<<"\",\"index\":"<<w.photochemistry[i].production_index<<'}';}o<<"]\n}\n";}
} // namespace worldgen
